-- =====================================================================================
-- Tibia Map - database step 26: Postman Missions Quest dialogs from the wiki (2026-11-24)
--
-- Run this once in Supabase (the house planner's project): SQL Editor -> New query -> paste everything -> Run.
-- Safe to run again.
--
-- What it does:
--   The drafted Kevin dialogs all used his first-visit replies (his script has a different "mission" answer for every
--   stage). Every talk step of the quest gets its dialog rebuilt from the NPC scripts, each line chosen by the reply in
--   the wiki's dialog transcriptions (Mission 1 as tested in the game by the user).
--   The wiki shows the title Assistant Postofficer comes with Mission 3 (no "advancement"): step 815 becomes that
--   whole conversation and step 816 (Mission 3 on its own) is deleted.
--   Part "Assistant Postman" is split (user: the map is too crowded): the postal routes (steps 808-864) and the Folda
--   mailbox (steps 811-815) in a new part.
-- =====================================================================================

do $$
declare
  seg bigint;
begin
  update public.map_quest_segments set name = 'Assistant Postman: postal routes' where id = 137;
  select id into seg from public.map_quest_segments where quest_id = 88 and name = 'Assistant Postman: Folda mailbox';
  if seg is null then
    insert into public.map_quest_segments (quest_id, sort, name) values (88, 15, 'Assistant Postman: Folda mailbox') returning id into seg;
  end if;
  update public.map_quest_steps set segment_id = seg where id in (811, 812, 813, 814, 815);
end $$;

delete from public.map_quest_steps where id = 816;

update public.map_quest_steps set dialog = '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]},{"say":"yes","reply":"Excellent! Your first task will be quite simple. But you should better write my instructions down anyways. You can read and write?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]},{"say":"yes","reply":"So listen, you will check certain tours our members have to take to see if there is some trouble. First travel with Captain Bluebear''s ship from Thais to Carlin, understood?","alts":[{"other":true,"reply":"I am sorry, but being illiterate disqualifies you from joining."}]},{"say":"yes","reply":"Excellent! Once you have done that you will travel with Uzon to Edron. You will find him in the Femor Hills. Understood?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]},{"say":"yes","reply":"Fine, fine! Next, travel with Captain Seahorse to the city of Venore. Understood?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]},{"say":"yes","reply":"Good! Finally, find the technomancer Brodrosch and travel with him to the Isle of Cormaya. After this passage report back to me here. Understood?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyyone."}]},{"say":"yes","reply":"Ok, remember: the Tibian mail service puts trust in you! Don''t fail and report back soon. Just tell me about your MISSION.","fx":["quest 227 becomes 1"],"alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]},{"say":"bye","reply":"Good bye.","fx":["ends the conversation"]}]'::jsonb where id = 809;
